"use client";

import { useEffect, useState } from "react";
import { Check, Star, Cpu, HardDrive, Gauge } from "lucide-react";

export default function PackagesPage() {
  const [packages, setPackages] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("/api/packages")
      .then((res) => res.json())
      .then((data) => {
        setPackages(data.packages || []);
        setLoading(false);
      })
      .catch(() => {
        setPackages([]);
        setLoading(false);
      });
  }, []);

  if (loading) return <p className="p-8 text-white">Loading...</p>;

  return (
    <div className="p-12 bg-[#0c0c0c] min-h-screen text-white">
      <h1 className="text-4xl font-bold mb-2">Pricing</h1>
      <p className="text-gray-400 mb-10">Choose a plan that fits your workflow.</p>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
        {packages.map((pkg: any) => (
          <div
            key={pkg.id}
            className={`
              relative rounded-2xl p-8 shadow-xl bg-[#111111] border border-[#1f1f1f]
              hover:border-gray-500 transition-all duration-300 
              ${pkg.isPopular ? "scale-[1.03] border-white/30 shadow-2xl" : ""}
            `}
          >
            {/* Popular Badge */}
            {pkg.isPopular && (
              <div className="absolute top-4 right-4 bg-white text-black px-3 py-1 rounded-full text-xs font-semibold flex items-center gap-1">
                <Star size={14} className="text-yellow-500" />
                Popular
              </div>
            )}

            {/* Title */}
            <h2 className="text-3xl font-semibold mb-1">{pkg.name}</h2>

            {/* Price */}
            <div className="mt-4 flex items-end gap-2">
              <span className="text-5xl font-bold">₹{pkg.price}</span>
              <span classname="text-gray-400 mb-1">/ month</span>
            </div>

            {/* Description */}
            <p className="text-gray-400 text-sm mt-2 mb-6">{pkg.description}</p>

            {/* Divider */}
            <div className="w-full h-px bg-gray-800 my-4"></div>

            {/* Features */}
            <ul className="space-y-3 text-gray-300 text-sm">
              {pkg.features?.map((feature: string, idx: number) => (
                <li key={idx} className="flex items-center gap-3">
                  <Check size={18} className="text-green-500" />
                  <span>{feature}</span>
                </li>
              ))}
            </ul>

            {/* Resource Specs (CPU / RAM / Storage) */}
            <div className="mt-6 space-y-2">
              <div className="flex items-center gap-2 text-gray-300">
                <Cpu size={18} /> {featureIfExists(pkg.features, "vCPU")}
              </div>
              <div className="flex items-center gap-2 text-gray-300">
                <Gauge size={18} /> {featureIfExists(pkg.features, "GB RAM")}
              </div>
              <div className="flex items-center gap-2 text-gray-300">
                <HardDrive size={18} />{" "}
                {featureIfExists(pkg.features, "NVMe Disk")}
              </div>
            </div>

            {/* CTA Button */}
            <button
              className="
                mt-8 w-full bg-white text-black py-3 rounded-xl 
                font-semibold hover:bg-gray-200 transition
              "
            >
              Choose {pkg.name}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

// Helper function: extract CPU/RAM/Storage line from features
function featureIfExists(features: string[], match: string) {
  return features.find((f) => f.includes(match)) || "";
}